package org.jsoup.nodes;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import org.mockito.Mockito;
import org.jsoup.parser.Document;
import org.jsoup.parser.ParseSettings;
import org.jsoup.parser.Parser;

public class CommentTest {

    @Test
    public void createComment_ReturnsComment() {
        // Given
        String data = "This is a comment";

        // When
        Comment comment = new Comment(data);

        // Then
        assertNotNull(comment);
        assertEquals(data, comment.getData());
        assertEquals("#comment", comment.nodeName());
    }

    @Test
    public void createComment_WithEmptyData_ReturnsEmptyComment() {
        // Given
        String data = "";

        // When
        Comment comment = new Comment(data);

        // Then
        assertNotNull(comment);
        assertTrue(comment.getData().isEmpty());
        assertEquals("#comment", comment.nodeName());
    }

    @Test
    public void outerHtmlHead_CommentsInsertedAsComments() throws IOException {
        // Given
        String data = "This is a comment";
        Comment comment = new Comment(data);

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Appendable accum = out;
        Document.OutputSettings outSettings = Mockito.mock(Document.OutputSettings.class);
        int depth = 0;

        // When
        comment.outerHtmlHead(accum, depth, outSettings);

        // Then
        assertEquals("<!--" + data + "-->", out.toString());
    }

    @Test
    public void outerHtmlTail_CommentsNotInsertedAsComments() throws IOException {
        // Given
        String data = "This is a comment";
        Comment comment = new Comment(data);
        Document.OutputSettings outSettings = Mockito.mock(Document.OutputSettings.class);

        ByteArrayOutputStream out = new ByteArrayOutputStream();
        Appendable accum = out;
        int depth = 0;

        // When
        comment.outerHtmlTail(accum, depth, outSettings);

        // Then
        assertEquals("", out.toString());
    }

    @Test
    public void clone_CommentsCloneCorrectly() {
        // Given
        String data = "This is a comment";
        Comment comment = new Comment(data);
        Document document = Mockito.mock(Document.class);
        Mockito.when(document.children()).thenReturn(Collections.singletonList(comment));

        // When
        Comment clonedComment = comment.clone();

        // Then
        assertNotNull(clonedComment);
        assertEquals(comment, clonedComment);
    }

